UPDATE experiment_run
   SET error = #{param3}
 WHERE tenant_id = #{param1} AND id = #{param2} AND status = 'paused'

UPDATE experiment_run
status = #{status}, error = #{error}, pause_kind = #{pauseKind}, pause_reason = #{pauseReason}, paused_at = now(), finished_at = now(), control_state = 'NONE', pause_requested_at = NULL,
WHERE tenant_id = #{param1} AND id = #{param2}

UPDATE experiment_run
   SET variables = #{param3}::jsonb, expanded_steps = #{param4}
 WHERE tenant_id = #{param1} AND id = #{param2}

UPDATE experiment_run_step
   SET status=#{param3}, run_id=#{param4}::bigint, finished_at=now(), error=#{param5}
 WHERE tenant_id=#{param1} AND id=#{param2}
